INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>AI Governance RAG System</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">\n    <link rel="stylesheet" href="style.css">\n</head>\n<body>\n    <div class="app-container">\n        <!-- Header -->\n        <header class="app-header">\n            <div class="header-logo">\n                <div class="logo-icon"></div>\n                <h1>AGORA RAG</h1>\n            </div>\n            \n            <div class="header-controls">\n                <div class="model-select-wrapper">\n                    <label for="model-select">LLM Model:</label>\n                    <select id="model-select">\n                        <option value="gemini-2.5-flash">Gemini 2.5 Flash (Fast)</option>\n                        <option value="gemini-1.5-flash">Gemini 1.5 Flash</option>\n                        <option value="gemini-2.5-pro">Gemini 2.5 Pro</option>\n                    </select>\n                </div>\n                \n                <div id="status-badge" class="status-badge disconnected">\n                    <span class="status-dot"></span>\n                    <span id="status-text">Connecting...</span>\n                </div>\n            </div>\n        </header>\n\n        <!-- Main Body -->\n        <main class="app-main">\n            <!-- Left Side: Chat Workspace -->\n            <section class="chat-section">\n                <div id="chat-messages" class="chat-messages">\n                    <!-- Welcome / Quick Starts -->\n                    <div class="welcome-card" id="welcome-card">\n                        <h2>Retrieval-Augmented Generation Dashboard</h2>\n                        <p>Ask questions grounded in the ETO AGORA AI Governance dataset. The system enforces strict grounding rules and provides verifiable source links.</p>\n                        \n                        <div class="quick-starts">\n                            <h3>Suggested Queries:</h3>\n                            <div class="quick-start-buttons">\n                                <button class="qs-btn" data-query="What is the goal of EO 13859?">Goal of EO 13859</button>\n                                <button class="qs-btn" data-query="What is the UK Artificial Intelligence (Regulation) Act 2024?">UK AI Regulation Act 2024</button>\n                                <button class="qs-btn" data-query="List some AI-related laws from U.S. states and localities.">U.S. State & Local Laws</button>\n                                <button class="qs-btn" data-query="How do I bake a chocolate cake?">Test Grounding (Cake recipe)</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Input area -->\n                <div class="input-container">\n                    <form id="query-form" class="query-form">\n                        <input type="text" id="query-input" placeholder="Ask a question about AI governance..." required autocomplete="off">\n                        <button type="submit" id="submit-btn" class="submit-btn">\n                            <span class="btn-text">Submit</span>\n                            <div class="loading-spinner hidden"></div>\n                        </button>\n                    </form>\n                </div>\n            </section>\n        </main>\n    </div>\n    <script src="app.js"></script>\n</body>\n</html>\n'

STYLE_CSS = '/* Premium Dark Glassmorphic Design System */\n:root {\n    --bg-dark: #0b0f19;\n    --bg-card: rgba(22, 28, 45, 0.45);\n    --border-color: rgba(255, 255, 255, 0.07);\n    --border-glow: rgba(0, 242, 254, 0.15);\n    \n    /* Neon Accents */\n    --accent-primary: #00f2fe; /* Neon Cyan */\n    --accent-secondary: #4facfe; /* Neon Blue */\n    --accent-success: #00e676; /* Bright Green */\n    --accent-warning: #ffb300; /* Warm Amber */\n    --accent-error: #ff1744; /* Electric Red */\n    \n    /* Typography */\n    --text-primary: #f1f5f9;\n    --text-secondary: #94a3b8;\n    --text-muted: #64748b;\n    --font-sans: \'Inter\', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n    --font-mono: \'JetBrains Mono\', monospace;\n    \n    /* Animations */\n    --transition-smooth: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n* {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n}\n\nbody {\n    font-family: var(--font-sans);\n    background: radial-gradient(circle at 50% 0%, #1e1b4b 0%, var(--bg-dark) 70%);\n    color: var(--text-primary);\n    min-height: 100vh;\n    overflow-x: hidden;\n    display: flex;\n    justify-content: center;\n}\n\n/* App Layout */\n.app-container {\n    width: 100%;\n    max-width: 1200px;\n    height: 100vh;\n    display: flex;\n    flex-direction: column;\n    border-left: 1px solid var(--border-color);\n    border-right: 1px solid var(--border-color);\n    background: rgba(11, 15, 25, 0.7);\n    backdrop-filter: blur(20px);\n    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);\n}\n\n/* Header */\n.app-header {\n    padding: 1rem 1.5rem;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-bottom: 1px solid var(--border-color);\n    background: rgba(11, 15, 25, 0.5);\n}\n\n.header-logo {\n    display: flex;\n    align-items: center;\n    gap: 0.75rem;\n}\n\n.logo-icon {\n    width: 1.5rem;\n    height: 1.5rem;\n    border-radius: 50%;\n    background: linear-gradient(135deg, var(--accent-primary) 0%, var(--accent-secondary) 100%);\n    box-shadow: 0 0 15px var(--accent-primary);\n}\n\n.header-logo h1 {\n    font-size: 1.25rem;\n    font-weight: 700;\n    letter-spacing: -0.025em;\n    background: linear-gradient(to right, #ffffff, #a5b4fc);\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n}\n\n.header-controls {\n    display: flex;\n    align-items: center;\n    gap: 1.5rem;\n}\n\n.model-select-wrapper {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.85rem;\n    color: var(--text-secondary);\n}\n\n#model-select {\n    background: rgba(30, 41, 59, 0.7);\n    color: var(--text-primary);\n    border: 1px solid var(--border-color);\n    padding: 0.35rem 0.75rem;\n    border-radius: 6px;\n    font-family: var(--font-sans);\n    outline: none;\n    cursor: pointer;\n    transition: var(--transition-smooth);\n}\n\n#model-select:hover, #model-select:focus {\n    border-color: var(--accent-primary);\n    box-shadow: 0 0 10px rgba(0, 242, 254, 0.1);\n}\n\n/* Status Badge */\n.status-badge {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    padding: 0.4rem 0.8rem;\n    border-radius: 30px;\n    font-size: 0.8rem;\n    font-weight: 500;\n    border: 1px solid transparent;\n    transition: var(--transition-smooth);\n}\n\n.status-badge.connected {\n    background: rgba(0, 230, 118, 0.1);\n    color: var(--accent-success);\n    border-color: rgba(0, 230, 118, 0.2);\n}\n\n.status-badge.disconnected {\n    background: rgba(255, 23, 68, 0.1);\n    color: var(--accent-error);\n    border-color: rgba(255, 23, 68, 0.2);\n}\n\n.status-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background-color: currentColor;\n    display: inline-block;\n}\n\n.connected .status-dot {\n    box-shadow: 0 0 8px var(--accent-success);\n    animation: pulse 1.8s infinite;\n}\n\n.disconnected .status-dot {\n    box-shadow: 0 0 8px var(--accent-error);\n    animation: pulse 1.8s infinite;\n}\n\n/* Main Layout */\n.app-main {\n    flex: 1;\n    display: flex;\n    overflow: hidden;\n}\n\n.chat-section {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n}\n\n/* Chat Messages */\n.chat-messages {\n    flex: 1;\n    padding: 1.5rem;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 1.5rem;\n    scroll-behavior: smooth;\n}\n\n/* Welcome Card */\n.welcome-card {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    border-radius: 12px;\n    padding: 2rem;\n    max-width: 650px;\n    margin: 2rem auto;\n    text-align: center;\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);\n    backdrop-filter: blur(10px);\n}\n\n.welcome-card h2 {\n    font-size: 1.5rem;\n    font-weight: 600;\n    margin-bottom: 0.75rem;\n    color: #ffffff;\n}\n\n.welcome-card p {\n    font-size: 0.95rem;\n    color: var(--text-secondary);\n    line-height: 1.6;\n    margin-bottom: 2rem;\n}\n\n.quick-starts {\n    text-align: left;\n}\n\n.quick-starts h3 {\n    font-size: 0.9rem;\n    font-weight: 600;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    margin-bottom: 0.75rem;\n}\n\n.quick-start-buttons {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n    gap: 0.75rem;\n}\n\n.qs-btn {\n    background: rgba(30, 41, 59, 0.4);\n    color: var(--text-primary);\n    border: 1px solid var(--border-color);\n    padding: 0.75rem 1rem;\n    border-radius: 8px;\n    cursor: pointer;\n    font-family: var(--font-sans);\n    font-size: 0.85rem;\n    text-align: left;\n    transition: var(--transition-smooth);\n}\n\n.qs-btn:hover {\n    border-color: var(--accent-primary);\n    background: rgba(0, 242, 254, 0.05);\n    transform: translateY(-2px);\n}\n\n/* Chat Bubbles */\n.message {\n    display: flex;\n    flex-direction: column;\n    max-width: 80%;\n    animation: fadeIn 0.3s ease-out;\n}\n\n.message.user {\n    align-self: flex-end;\n}\n\n.message.assistant {\n    align-self: flex-start;\n}\n\n.message-bubble {\n    padding: 1rem 1.25rem;\n    border-radius: 12px;\n    font-size: 0.95rem;\n    line-height: 1.6;\n    word-break: break-word;\n}\n\n.user .message-bubble {\n    background: linear-gradient(135deg, var(--accent-secondary) 0%, #312e81 100%);\n    color: #ffffff;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    box-shadow: 0 4px 15px rgba(79, 254, 254, 0.05);\n    border-bottom-right-radius: 2px;\n}\n\n.assistant .message-bubble {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    color: var(--text-primary);\n    border-bottom-left-radius: 2px;\n}\n\n.message-meta {\n    font-size: 0.75rem;\n    color: var(--text-muted);\n    margin-top: 0.35rem;\n    font-weight: 500;\n}\n\n.user .message-meta {\n    align-self: flex-end;\n}\n\n/* Collapsible Source References */\n.references-container {\n    margin-top: 1rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}\n\n.ref-toggle-header {\n    font-size: 0.8rem;\n    color: var(--accent-secondary);\n    font-weight: 600;\n    cursor: pointer;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    user-select: none;\n    margin-bottom: 0.25rem;\n    transition: var(--transition-smooth);\n}\n\n.ref-toggle-header:hover {\n    color: var(--accent-primary);\n}\n\n.ref-toggle-header::before {\n    content: \'▶\';\n    display: inline-block;\n    font-size: 0.65rem;\n    transition: transform 0.2s;\n}\n\n.ref-toggle-header.active::before {\n    transform: rotate(90deg);\n}\n\n.references-list {\n    display: none;\n    flex-direction: column;\n    gap: 0.50rem;\n    padding-left: 0.5rem;\n    border-left: 1px solid rgba(79, 254, 254, 0.2);\n    margin-top: 0.25rem;\n    animation: slideDown 0.25s ease-out;\n}\n\n.references-list.show {\n    display: flex;\n}\n\n.ref-card {\n    background: rgba(30, 41, 59, 0.3);\n    border: 1px solid var(--border-color);\n    border-radius: 8px;\n    padding: 0.75rem;\n    font-size: 0.85rem;\n}\n\n.ref-card-title {\n    font-weight: 600;\n    color: #ffffff;\n    margin-bottom: 0.25rem;\n}\n\n.ref-card-meta {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.75rem;\n    color: var(--text-secondary);\n    font-size: 0.75rem;\n    margin-bottom: 0.35rem;\n}\n\n.ref-card-meta span {\n    display: inline-flex;\n    align-items: center;\n}\n\n.ref-card-link {\n    color: var(--accent-primary);\n    text-decoration: none;\n    font-weight: 500;\n}\n\n.ref-card-link:hover {\n    text-decoration: underline;\n}\n\n/* Input Bar */\n.input-container {\n    padding: 1.5rem;\n    border-top: 1px solid var(--border-color);\n    background: rgba(11, 15, 25, 0.6);\n}\n\n.query-form {\n    display: flex;\n    gap: 0.75rem;\n}\n\n#query-input {\n    flex: 1;\n    background: rgba(15, 23, 42, 0.8);\n    border: 1px solid var(--border-color);\n    border-radius: 8px;\n    padding: 0.85rem 1.25rem;\n    color: var(--text-primary);\n    font-family: var(--font-sans);\n    font-size: 0.95rem;\n    outline: none;\n    transition: var(--transition-smooth);\n}\n\n#query-input:focus {\n    border-color: var(--accent-primary);\n    box-shadow: 0 0 15px var(--border-glow);\n    background: rgba(15, 23, 42, 0.95);\n}\n\n.submit-btn {\n    background: linear-gradient(135deg, var(--accent-secondary) 0%, #1e40af 100%);\n    color: #ffffff;\n    border: none;\n    border-radius: 8px;\n    padding: 0 1.5rem;\n    font-family: var(--font-sans);\n    font-weight: 600;\n    font-size: 0.95rem;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    min-width: 90px;\n    transition: var(--transition-smooth);\n}\n\n.submit-btn:hover:not(:disabled) {\n    transform: translateY(-2px);\n    box-shadow: 0 5px 15px rgba(59, 130, 246, 0.3);\n}\n\n.submit-btn:disabled {\n    opacity: 0.6;\n    cursor: not-allowed;\n}\n\n/* Spinner */\n.loading-spinner {\n    width: 20px;\n    height: 20px;\n    border: 2px solid rgba(255, 255, 255, 0.3);\n    border-radius: 50%;\n    border-top-color: #ffffff;\n    animation: spin 0.8s linear infinite;\n}\n\n.hidden {\n    display: none;\n}\n\n/* Animations */\n@keyframes spin {\n    to { transform: rotate(360deg); }\n}\n\n@keyframes pulse {\n    0% { opacity: 0.6; transform: scale(1); }\n    50% { opacity: 1; transform: scale(1.15); }\n    100% { opacity: 0.6; transform: scale(1); }\n}\n\n@keyframes fadeIn {\n    from { opacity: 0; transform: translateY(10px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n@keyframes slideDown {\n    from { opacity: 0; transform: translateY(-5px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n/* Responsive CSS Media Queries (Mobile & Tablet) */\n@media (max-width: 768px) {\n    .app-container {\n        height: 100vh;\n        border: none;\n    }\n    \n    .app-header {\n        flex-direction: column;\n        align-items: stretch;\n        gap: 0.75rem;\n        padding: 0.75rem 1rem;\n    }\n    \n    .header-controls {\n        justify-content: space-between;\n        width: 100%;\n        gap: 0.75rem;\n    }\n    \n    .model-select-wrapper {\n        font-size: 0.8rem;\n    }\n    \n    .status-badge {\n        padding: 0.3rem 0.6rem;\n        font-size: 0.75rem;\n    }\n    \n    .chat-messages {\n        padding: 1rem;\n        gap: 1rem;\n    }\n    \n    .message {\n        max-width: 90%;\n    }\n    \n    .welcome-card {\n        padding: 1.5rem 1rem;\n        margin: 1rem 0;\n    }\n    \n    .welcome-card h2 {\n        font-size: 1.3rem;\n    }\n    \n    .quick-start-buttons {\n        grid-template-columns: 1fr;\n        gap: 0.5rem;\n    }\n    \n    .qs-btn {\n        padding: 0.6rem 0.8rem;\n        font-size: 0.8rem;\n    }\n    \n    .input-container {\n        padding: 1rem;\n    }\n    \n    .query-form {\n        gap: 0.5rem;\n    }\n    \n    #query-input {\n        padding: 0.75rem 1rem;\n        font-size: 0.9rem;\n    }\n    \n    .submit-btn {\n        padding: 0 1rem;\n        font-size: 0.9rem;\n        min-width: 75px;\n    }\n}\n'

APP_JS = 'document.addEventListener("DOMContentLoaded", () => {\n    const queryForm = document.getElementById("query-form");\n    const queryInput = document.getElementById("query-input");\n    const submitBtn = document.getElementById("submit-btn");\n    const btnText = submitBtn.querySelector(".btn-text");\n    const spinner = submitBtn.querySelector(".loading-spinner");\n    const chatMessages = document.getElementById("chat-messages");\n    const welcomeCard = document.getElementById("welcome-card");\n    const modelSelect = document.getElementById("model-select");\n    const statusBadge = document.getElementById("status-badge");\n    const statusText = document.getElementById("status-text");\n\n    // Check backend connection status and load DB stats\n    async function checkStatus() {\n        try {\n            const res = await fetch("/api/status");\n            const data = await res.json();\n            \n            if (data.connected) {\n                statusBadge.className = "status-badge connected";\n                statusText.textContent = `Connected: ${data.indexed_chunks} chunks`;\n            } else {\n                statusBadge.className = "status-badge disconnected";\n                statusText.textContent = "Disconnected (No DB)";\n            }\n        } catch (e) {\n            statusBadge.className = "status-badge disconnected";\n            statusText.textContent = "Offline (Server down)";\n            console.error("Status check failed:", e);\n        }\n    }\n\n    // Call status immediately\n    checkStatus();\n\n    // Bind Quick Start buttons\n    document.querySelectorAll(".qs-btn").forEach(btn => {\n        btn.addEventListener("click", () => {\n            const query = btn.dataset.query;\n            queryInput.value = query;\n            queryForm.dispatchEvent(new Event("submit"));\n        });\n    });\n\n    // Handle Form Submission\n    queryForm.addEventListener("submit", async (e) => {\n        e.preventDefault();\n        const query = queryInput.value.trim();\n        if (!query) return;\n\n        // Disable input during request\n        queryInput.disabled = true;\n        submitBtn.disabled = true;\n        btnText.classList.add("hidden");\n        spinner.classList.remove("hidden");\n\n        // Remove welcome card on first submission\n        if (welcomeCard) {\n            welcomeCard.remove();\n        }\n\n        // 1. Add User Message\n        appendMessage("user", query);\n        queryInput.value = "";\n\n        // Scroll to bottom\n        chatMessages.scrollTop = chatMessages.scrollHeight;\n\n        try {\n            // 2. Fetch answer from API\n            const response = await fetch("/api/query", {\n                method: "POST",\n                headers: { "Content-Type": "application/json" },\n                body: JSON.stringify({\n                    query: query,\n                    model: modelSelect.value,\n                    k: 4\n                })\n            });\n\n            if (!response.ok) {\n                const errData = await response.json();\n                throw new Error(errData.detail || "Query failed");\n            }\n\n            const data = await response.json();\n\n            // 3. Add Assistant Message\n            appendMessage("assistant", data.answer, data.references);\n\n        } catch (err) {\n            appendMessage("assistant", `Error executing query: ${err.message}. Please verify your API key and database connection.`);\n        } finally {\n            // Re-enable input controls\n            queryInput.disabled = false;\n            submitBtn.disabled = false;\n            btnText.classList.remove("hidden");\n            spinner.classList.add("hidden");\n            queryInput.focus();\n            \n            // Scroll to bottom\n            chatMessages.scrollTop = chatMessages.scrollHeight;\n        }\n    });\n\n    // Helper: Append a message bubble to the chat workspace\n    function appendMessage(sender, text, references = []) {\n        const messageDiv = document.createElement("div");\n        messageDiv.className = `message ${sender}`;\n\n        const bubbleDiv = document.createElement("div");\n        bubbleDiv.className = "message-bubble";\n        bubbleDiv.textContent = text;\n        messageDiv.appendChild(bubbleDiv);\n\n        // Render Collapsible References if present (only for assistant messages)\n        if (sender === "assistant" && references && references.length > 0) {\n            const refContainer = document.createElement("div");\n            refContainer.className = "references-container";\n\n            const toggleHeader = document.createElement("div");\n            toggleHeader.className = "ref-toggle-header";\n            toggleHeader.textContent = `Source References (${references.length})`;\n            \n            const refList = document.createElement("div");\n            refList.className = "references-list";\n\n            references.forEach((ref) => {\n                const refCard = document.createElement("div");\n                refCard.className = "ref-card";\n\n                const refTitle = document.createElement("div");\n                refTitle.className = "ref-card-title";\n                refTitle.textContent = ref.title || `Document ${ref.doc_id}`;\n\n                const refMeta = document.createElement("div");\n                refMeta.className = "ref-card-meta";\n\n                const sourceSpan = document.createElement("span");\n                sourceSpan.textContent = `File: ${ref.source} (Chunk ${ref.chunk_index})`;\n                refMeta.appendChild(sourceSpan);\n\n                if (ref.authority) {\n                    const authSpan = document.createElement("span");\n                    authSpan.textContent = `| Authority: ${ref.authority}`;\n                    refMeta.appendChild(authSpan);\n                }\n\n                if (ref.collections) {\n                    const collSpan = document.createElement("span");\n                    collSpan.textContent = `| Category: ${ref.collections}`;\n                    refMeta.appendChild(collSpan);\n                }\n\n                refCard.appendChild(refTitle);\n                refCard.appendChild(refMeta);\n\n                if (ref.link) {\n                    const refLink = document.createElement("a");\n                    refLink.href = ref.link;\n                    refLink.target = "_blank";\n                    refLink.className = "ref-card-link";\n                    refLink.textContent = "View Official Document ↗";\n                    refCard.appendChild(refLink);\n                }\n\n                refList.appendChild(refCard);\n            });\n\n            // Toggle logic\n            toggleHeader.addEventListener("click", () => {\n                const isOpen = refList.classList.contains("show");\n                if (isOpen) {\n                    refList.classList.remove("show");\n                    toggleHeader.classList.remove("active");\n                } else {\n                    refList.classList.add("show");\n                    toggleHeader.classList.add("active");\n                }\n                chatMessages.scrollTop = chatMessages.scrollHeight;\n            });\n\n            refContainer.appendChild(toggleHeader);\n            refContainer.appendChild(refList);\n            bubbleDiv.appendChild(refContainer);\n        }\n\n        const metaDiv = document.createElement("div");\n        metaDiv.className = "message-meta";\n        const time = new Date().toLocaleTimeString([], { hour: \'2-digit\', minute: \'2-digit\' });\n        metaDiv.textContent = sender === "user" ? `You • ${time}` : `AI • ${time}`;\n        messageDiv.appendChild(metaDiv);\n\n        chatMessages.appendChild(messageDiv);\n        chatMessages.scrollTop = chatMessages.scrollHeight;\n    }\n});\n'
